arguments.command:
sed -i 's/^exit \$fail/[ "$(bash bin/price 999)" = 899 ] || { echo "price 999"; fail=1; }
[ "$(bash bin/quote 999)" = "quote: 899" ] || { echo "quote 999"; fail=1; }
[ "$(bash lib/invoice.sh 999)" = "member total 899" ] || { echo "invoice 999"; fail=1; }
exit $fail/' tests/price_test.sh
cat tests/price_test.sh; bash scripts/verify.sh; echo "green=$?"
git stash -q -- bin lib; bash scripts/verify.sh; echo "red(before fix)=$?"; git stash pop -q; git status --short

